from PIL import Image
def find_bores2(path):
    im=Image.open(path).convert("RGB")
    w,h=im.size
    pix=im.load()
    pts=[]
    for y in range(290,h):
        for x in range(w):
            r,g,b=pix[x,y]
            if r<80 and g<80 and b<80:
                pts.append((x,y))
    if not pts:
        print(path, "none")
        return []
    xs=sorted([p[0] for p in pts])
    gaps=sorted([(xs[i+1]-xs[i], i) for i in range(len(xs)-1)], reverse=True)
    _, idx=gaps[0]
    thresh=(xs[idx]+xs[idx+1])//2
    c1=[p for p in pts if p[0]<=thresh]
    c2=[p for p in pts if p[0]>thresh]
    def cent(c):
        return (sum(p[0] for p in c)/len(c), sum(p[1] for p in c)/len(c), len(c))
    return [cent(c1), cent(c2)]

import os
files=["wrist_008.png","wrist_009.png","wrist_010.png","wrist_011.png","wrist_012.png"]
for f in files:
    res=find_bores2(f"/home/robot/captures/{f}")
    print(f, res)
PY"}

